fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let ax: i32 = w / 2 - 12;
    let ay: i32 = h / 2 - 12;
    host::display::clear(0x000000);
    let mut i: i32 = 0;
    while i < 48 {
        let s: i32 = t - i;
        let x: i32 = cx + tab[(s * 3 / 2) & 31] * ax / 127;
        let y: i32 = cy + tab[(s + 8) & 31] * ay / 127;
        let c: i32 = if i < 4 { 0x00ffcc } else if i < 20 { 0x008877 } else { 0x004033 };
        host::display::fill_rect(x - 2, y - 2, 4, 4, c);
        i = i + 1;
    }
    host::display::present();
}
